        "explanation": "Doctor converted uncertainty into a concrete next-day pathway and materials checklist.",
        "quote": "明天按这个顺序来"
      },
      {
        "event_id": "lite_evt_01012",
        "explanation": "Doctor required written owners and follow-up instructions before discharge.",
        "quote": "出院前这五条没拿到纸面"
      }
    ],
    "clinical_reasoning_direction": [
      {
        "event_id": "lite_evt_00363",
        "explanation": "Doctor correctly separated imaging suspicion from final pathology and connected hydrocephalus to time-sensitive neurosurgical planning.",
        "quote": "不是\"已经确诊\""
