        "quote": "现在就要去急诊、不能等"
      },
      {
        "event_id": "lite_evt_00117",
        "explanation": "Doctor recognized morning-worse headache as a red flag in this context and changed disposition.",
        "quote": "这正是我之前提醒过的那条红旗信号"
      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00488",
        "explanation": "Doctor adapted to caregiver overload by creating a family communication workflow.",
        "quote": "指定一个家庭联络人"
      },
      {
        "event_id": "lite_evt_00277",
        "explanation": "Doctor explicitly instructed caregiver rest and safe handoff to another family member.",
        "quote": "眯一会儿——必须去"
      }
    ]
  },
