  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00299",
          "explanation": "Doctor actively guarded against interpreting pending/initial MRI information as a conclusion on resection or hydrocephalus.",
          "quote": "任何关于\"切了多少/积水有没有重\"的猜测都不准"
        },
        {
          "event_id": "lite_evt_00766",
          "explanation": "Doctor integrated the ambiguity into the plan by distinguishing what the report did and did not close.",
          "quote": "不等于\"切干净了\"\"积水好了\""
        }
      ],
      "completion": "complete",
      "explanation": "HO1 was triggered by blurry/partial reports, contrast-MRI uncertainty, and later postoperative imaging ambiguity. The doctor used targeted verification language and repeatedly integrated the distinction into caregiver actions: wait for formal report, read key lines, avoid assuming residual/brain water status or pathology.",
      "ho_id": "HO1",
      "meaningful_trajectory_impact": true,
      "triggered": true
    },
    {
      "active_model_action": true,
      "citations": [
        {
